/*
 * A077720  Primes which can be expressed as sum of distinct powers of 6.
 * https://oeis.org/A077720
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the nth prime whose base‑6 representation consists only
 *            of 0’s and 1’s. Generated by iterating binary numbers (bits
 *            0/1), interpreting them as base‑6 digits to obtain values
 *            sum(6^i * bit_i) and testing each for primality. Results are
 *            cached so that calls need not recompute earlier values
 * Range:     u8 n <= 4, u16 n <= 12, u32 n <= 525, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   isPrimeGeneric
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include "../utils/isPrimeGeneric.h"

seq_t a(idx_t n) {
    /* static cache of found primes */
    static seq_t *prime_cache = NULL;
    static size_t cache_len = 0, cache_cap = 0;

    /* next binary number to test (starting from 1) */
    static uint64_t next_bin = 1;

    /* pre‑computed powers of 6 (up to 2^64-1) */
    static uint64_t pow6[64];
    static int pow6_len = 0;

    /* initialise powers of 6 on first call */
    if (pow6_len == 0) {
        pow6[0] = 1;
        pow6_len = 1;
        while (pow6_len < 64) {
            __uint128_t tmp = (__uint128_t)pow6[pow6_len - 1] * 6;
            if (tmp > (unsigned __int128)UINT64_MAX) break;
            pow6[pow6_len++] = (uint64_t)tmp;
        }
    }

    /* generate primes until we have at least n of them */
    while (cache_len < (size_t)n) {
        /* compute the candidate value as sum of 6^i for set bits of next_bin */
        seq_t val = 0;
        uint64_t bb = next_bin;
        int i = 0;
        while (bb && i < pow6_len) {
            if (bb & 1ULL) val += pow6[i];
            bb >>= 1;
            i++;
        }

        /* test primality (>=2) and add to cache if prime */
        if (val >= 2 && isPrimeGeneric(val)) {
            if (cache_len == cache_cap) {
                cache_cap = cache_cap ? cache_cap * 2 : 128;
                prime_cache = (seq_t *)realloc(prime_cache, cache_cap * sizeof(seq_t));
            }
            prime_cache[cache_len++] = val;
        }

        next_bin++;  /* move to the next binary number */
    }

    return prime_cache[n - 1];
}
